use serde::{Deserialize,Serialize};
const DEFAULT_APP_SHORTCUT:&str="Alt+Shift+S";
#[derive(Clone, Copy, Debug, Deserialize, Serialize, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
enum PersistedWindowMode {
    Full,
    Quick,
}

#[derive(Clone, Debug, Deserialize, Serialize, PartialEq, Eq)]
#[serde(default, rename_all = "camelCase")]
pub struct DesktopSettings {
    pub background_mode_enabled: bool,
    pub shortcut_enabled: bool,
    pub shortcut: String,
    pub remember_window_bounds: bool,
}

impl Default for DesktopSettings {
    fn default() -> Self {
        Self {
            background_mode_enabled: true,
            shortcut_enabled: true,
            shortcut: DEFAULT_APP_SHORTCUT.to_string(),
            remember_window_bounds: true,
        }
    }
}

#[derive(Clone, Debug, Deserialize, Serialize, Default)]
#[serde(rename_all = "camelCase")]
struct PersistedDesktopState {
    #[serde(default)]
    settings: DesktopSettings,
    #[serde(default)]
    last_full_window_layout: Option<FullWindowLayoutSnapshot>,
    #[serde(default)]
    last_window_mode: Option<PersistedWindowMode>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
struct FullWindowLayoutSnapshot {
    x: i32,
    y: i32,
    width: u32,
    height: u32,
    maximized: bool,
}

fn main(){
 let old=r#"{"backgroundModeEnabled":false,"shortcutEnabled":false,"shortcut":"Ctrl+K","rememberWindowBounds":false}"#;
 let nested=serde_json::from_str::<PersistedDesktopState>(old).unwrap();
 let legacy=serde_json::from_str::<DesktopSettings>(old).unwrap();
 assert!(nested.settings.background_mode_enabled);assert!(!legacy.background_mode_enabled);
 assert_eq!(nested.settings.shortcut,"Alt+Shift+S");assert_eq!(legacy.shortcut,"Ctrl+K");
 println!("{{\"legacy_flat_json_accepted_by_new_schema\":true,\"legacy_settings_silently_defaulted\":true,\"direct_legacy_parse_preserves_settings\":true}}");
}
